INTRO = "Moved by Lidia's loyalty, Paquita gets back on her feet right away. She phones a casting director to fight for Lidia in Puente Viejo, finally sits down to watch the showreel of Álex's cousin, and calls Magüi to apologise. Let's listen in Spanish first."
STORY = [('paquita', 'Hola, soy Paquita Salas. Mira, perdona que te llame ahora.', 'Hello, this is Paquita Salas. Look, sorry to call you right now.', [(330, 'Hola'), (331, 'soy Paquita Salas. Mira, perdona que te llame ahora')], ''), ('paquita', 'Es que tengo una actriz que necesito que veas. Se llama Lidia San José.', 'I have an actress I need you to see. Her name is Lidia San José.', [(332, 'Es que tengo una actriz que necesito que veas'), (333, 'Se llama Lidia San José')], ''), ('director', '¿Lidia San José? A ver, Paquita, ¿y por qué la tengo que ver?', 'Lidia San José? Come on, Paquita, and why do I have to see her?', [(334, 'Lidia San José'), (336, 'A ver, Paquita, ¿y por qué la tengo que ver?')], ''), ('paquita', 'Pues porque la tienes que ver, porque no sabes cómo es, de verdad.', 'Because you have to see her—you have no idea how good she is, really.', [(337, 'Pues porque la tienes que ver, porque no sabes cómo es, de verdad')], ''), ('paquita', 'Lo ha hecho todo. Sabe hacerlo todo.', "She's done everything. She knows how to do it all.", [(339, 'Lo ha hecho todo. Sabe hacerlo todo')], ''), ('director', 'Hay un papel pequeño en Puente Viejo, pero no creo que Lidia encaje.', "There's a small role in Puente Viejo, though I don't think Lidia fits.", [(340, 'Hay un papel pequeño en'), (340, 'Puente Viejo'), (341, 'pero no creo que Lidia encaje')], ''), ('paquita', 'Me da igual. Si hay alguien que encaja en Puente Viejo, esa es Lidia San José.', "I don't care. If anyone fits in Puente Viejo, it's Lidia San José.", [(341, 'Me da igual'), (342, 'Si hay alguien que encaja en'), (342, 'esa es Lidia San José')], ''), ('director', 'Vale, vale, Paquita, lo miramos.', "Alright, alright, Paquita, we'll look into it.", [(343, 'Vale, vale, Paquita, lo miramos')], ''), ('paquita', 'Hasta luego.', 'Bye for now.', [(343, 'Hasta luego')], ''), ('sofi', 'En verdad estoy enamorada de ti. No espero que te enamores de mí por eso, pero piénsatelo.', "Truthfully, I'm in love with you. I don't expect you to fall in love with me because of that, just think about it.", [(346, 'En verdad estoy enamorada de ti'), (347, 'No espero que te enamores de mí por eso, pero piénsatelo')], ''), ('sofi', 'Ahí estaré yo para recoger los pedacitos.', "I'll be right there to pick up the little pieces.", [(353, 'ahí estaré yo para recoger los pedacitos')], ''), ('paquita', 'Magüi. Magüi, lo siento.', "Magüi. Magüi, I'm sorry.", [(354, 'Magüi'), (355, 'Magüi, lo siento')], '')]
